#!/usr/bin/env bash
set -euo pipefail

BASE="$HOME/PokemonRedExperiments-v2/v2"
PYENV="$HOME/miniconda3/envs/pokemonredv2/bin/python"
BACKUP_ROOT="$HOME/pokemonred_backups"

cd "$BASE"

echo "============================================================"
echo " Pokemon Red AI V3 - Fresh Zero Installer"
echo "============================================================"
echo
echo "V3 architectuur:"
echo "  Agent 1     = persistent READ-ONLY explorer"
echo "  Agents 2-12 = 11 enige PPO-trainingagents"
echo "  Agent 1     = gebruikt actuele PPO-policy via model.predict()"
echo "  Agent 1     = schrijft GEEN rollout-data naar PPO"
echo "  Agent 1     = geen normale max_steps reset"
echo "  Agent 1     = steps/heal/explore/reward lopen door binnen het proces"
echo
echo "Deze installer START de bot NIET."
echo

check_hash() {
    local file="$1"
    local expected="$2"
    local actual
    actual="$(sha256sum "$file" | awk '{print $1}')"
    if [[ "$actual" != "$expected" ]]; then
        echo "FOUT: $file wijkt af van de toestand die net op de rig werd gecontroleerd."
        echo "Verwacht: $expected"
        echo "Actueel : $actual"
        echo "Er wordt niets gewijzigd."
        exit 1
    fi
    echo "OK: $file"
}

echo "== 1. Exacte huidige broncode controleren =="
check_hash baseline_fast_v2.py "074abd8461e51e57eea0fcdb70550983d76f2d97495ef91750a280e0a651e610"
check_hash red_gym_env_v2.py "ebdd7c37d353a0ad39f1416b9f0a0f13c7f57508a39f888de6093c38d0689765"
check_hash tensorboard_callback.py "8d9845ecb20144ba49d83a5dfa899de61f40a6d9fd73249a1bbd417aaea0c526"
check_hash live_server.py "52364fcdb80e890ef03ce1fb45689468c18ab10aad497a28341ddd45af018fde"
check_hash persistent_explorer_callback.py "f0b6efee6fe8f042678bec8f82f6a8b0163b5de800b31431b4a7756e62151b9b"
echo

echo "== 2. Controleren dat de bot uit staat en geheugen echt leeg is =="
if pgrep -f '[b]aseline_fast_v2.py' >/dev/null 2>&1; then
    echo "FOUT: baseline_fast_v2.py draait nog."
    exit 1
fi
if ss -ltnp 2>/dev/null | grep -Eq ':8080|:6006'; then
    echo "FOUT: 8080 of 6006 luistert nog. Stop viewer/TensorBoard eerst."
    exit 1
fi

LEFTOVERS="$(find runs -mindepth 1 -maxdepth 2 ! -name '.gitignore' -print)"
if [[ -n "$LEFTOVERS" ]]; then
    echo "FOUT: runs/ is niet volledig leeg:"
    echo "$LEFTOVERS"
    exit 1
fi

echo "OK: bot uit, poorten uit, runs/ leeg."
echo

echo "== 3. Definitieve V3-code offline bouwen en testen =="
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

cat > "$TMP/baseline_fast_v2.py.b64" <<'EOF_baseline_fast_v2_py'

EOF_baseline_fast_v2_py
base64 -d "$TMP/baseline_fast_v2.py.b64" > "$TMP/baseline_fast_v2.py"

cat > "$TMP/persistent_explorer_callback.py.b64" <<'EOF_persistent_explorer_callback_py'

EOF_persistent_explorer_callback_py
base64 -d "$TMP/persistent_explorer_callback.py.b64" > "$TMP/persistent_explorer_callback.py"

cat > "$TMP/tensorboard_callback.py.b64" <<'EOF_tensorboard_callback_py'

EOF_tensorboard_callback_py
base64 -d "$TMP/tensorboard_callback.py.b64" > "$TMP/tensorboard_callback.py"

cat > "$TMP/live_server.py.b64" <<'EOF_live_server_py'

EOF_live_server_py
base64 -d "$TMP/live_server.py.b64" > "$TMP/live_server.py"

cat > "$TMP/red_gym_env_v2.py.b64" <<'EOF_red_gym_env_v2_py'

EOF_red_gym_env_v2_py
base64 -d "$TMP/red_gym_env_v2.py.b64" > "$TMP/red_gym_env_v2.py"


"$PYENV" -m py_compile \
    "$TMP/baseline_fast_v2.py" \
    "$TMP/persistent_explorer_callback.py" \
    "$TMP/tensorboard_callback.py" \
    "$TMP/live_server.py" \
    "$TMP/red_gym_env_v2.py"

"$PYENV" - "$TMP" <<'PY'
from pathlib import Path
import sys

root = Path(sys.argv[1])
baseline = (root / "baseline_fast_v2.py").read_text()
explorer = (root / "persistent_explorer_callback.py").read_text()
env = (root / "red_gym_env_v2.py").read_text()
tb = (root / "tensorboard_callback.py").read_text()

checks = [
    ('num_train_envs = 11' in baseline,
     "PPO heeft exact 11 training environments"),
    ('logical_agent_number = rank + 2' in baseline,
     "PPO environments zijn logisch Agents 2-12"),
    ('rank_conf["persistent_agent"] = False' in baseline,
     "geen PPO training env is persistent"),
    ('PersistentExplorerCallback' in baseline,
     "aparte Agent-1 callback is gekoppeld"),
    ('reset_num_timesteps=not resumed_from_checkpoint' in baseline,
     "nieuwe training start teller op 0; checkpoint-resume loopt door"),
    ('self.model.predict(self.obs, deterministic=False)' in explorer,
     "Agent 1 leest de actuele PPO-policy via model.predict"),
    ('rollout_buffer' not in explorer,
     "Agent 1 callback raakt PPO rollout_buffer niet"),
    ('"persistent_agent": True' in explorer,
     "Agent 1 gebruikt een eigen persistent environment"),
    ('if self.persistent_agent:\n            return False' in env,
     "Agent 1 krijgt geen normale max_steps reset"),
    ('indices=[0]' in tb,
     "TensorBoard episode-trigger gebruikt eerste echte PPO-agent"),
]

failed = [msg for ok, msg in checks if not ok]
if failed:
    print("FOUT: V3 architectuurcheck faalde:")
    for msg in failed:
        print(" -", msg)
    raise SystemExit(1)

print("V3 architectuurchecks: OK")
for _, msg in checks:
    print(" -", msg)
PY
echo

echo "== 4. Volledige backup maken vóór installatie =="
mkdir -p "$BACKUP_ROOT"
STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="$BACKUP_ROOT/PokemonRedExperiments-v2_before_V3_${STAMP}.tar.gz"

tar -czf "$BACKUP" -C "$HOME" PokemonRedExperiments-v2
sha256sum "$BACKUP" > "$BACKUP.sha256"
sha256sum -c "$BACKUP.sha256"

echo "Backup: $BACKUP"
echo

echo "== 5. Definitieve V3-files installeren =="
install -m 664 "$TMP/baseline_fast_v2.py" "$BASE/baseline_fast_v2.py"
install -m 664 "$TMP/persistent_explorer_callback.py" "$BASE/persistent_explorer_callback.py"
install -m 664 "$TMP/tensorboard_callback.py" "$BASE/tensorboard_callback.py"
install -m 664 "$TMP/live_server.py" "$BASE/live_server.py"
install -m 664 "$TMP/red_gym_env_v2.py" "$BASE/red_gym_env_v2.py"

"$PYENV" -m py_compile \
    baseline_fast_v2.py \
    persistent_explorer_callback.py \
    tensorboard_callback.py \
    live_server.py \
    red_gym_env_v2.py

echo
echo "== 6. Geïnstalleerde hashes =="
sha256sum \
    baseline_fast_v2.py \
    red_gym_env_v2.py \
    tensorboard_callback.py \
    live_server.py \
    persistent_explorer_callback.py

echo
echo "============================================================"
echo " POKEMON RED AI V3 - INSTALLATIE GESLAAGD"
echo "============================================================"
echo
echo "Bot staat nog UIT."
echo
echo "Volgende start zonder checkpoint:"
echo "  PPO              = volledig vanaf 0"
echo "  PPO steps        = vanaf 0"
echo "  Agent 1 wereld   = vanaf init.state"
echo "  Agents 2-12      = vanaf init.state"
echo "  oud AI-geheugen  = niets geladen"
echo
echo "V3:"
echo "  Agent 1     = persistent read-only explorer"
echo "  Agents 2-12 = enige PPO trainers"
echo
echo "Backup:"
echo "  $BACKUP"
echo
echo "Nu kunnen we de Git repository proper maken vóór de eerste V3-training."
